mapper.select:
SELECT * FROM (
	SELECT Tb.*, rownum rNum FROM (
		SELECT * FROM coupon
		WHERE 1=1
		
			AND MemberId=#{memberId}
		
		ORDER BY coupon_no DESC
	) Tb
)
WHERE rNum >= #{start}
AND rNum <= #{end}

mapper.insert:
DECLARE
next_no NUMBER;
BEGIN
getnext_coupon_no(next_no);
INSERT INTO coupon (coupon_no, memberId, thumbnail, coupon_name, coupon_code, discount, minimum, date_start, date_end, used, created_date)
VALUES (next_no, #{memberId}, #{thumbnail, jdbcType=VARCHAR}, #{coupon_name}, #{coupon_code, jdbcType=VARCHAR}, #{discount}, #{minimum, jdbcType=NUMERIC}, #{date_start}, #{date_end}, #{used}, CURRENT_TIMESTAMP);
END;

mapper.select:
SELECT * FROM coupon
WHERE 1=1
AND date_end >= TRUNC(SYSDATE)
AND coupon_code=#{coupon_code}
AND MemberId=#{memberId}
